UPDATE `sessions` SET `updated_at` = max(`updated_at`, coalesce((SELECT max(CAST(round(unixepoch(json_extract(`message_json`, '$.createdAt'), 'subsec') * 1000) AS INTEGER)) FROM `chat_messages` WHERE `chat_messages`.`thread_id` = `sessions`.`id` AND json_type(`message_json`, '$.createdAt') = 'text'), `updated_at`));--> statement-breakpoint
UPDATE `sessions` SET `title` = (SELECT nullif(substr(trim(CASE json_type(`message_json`, '$.content') WHEN 'text' THEN json_extract(`message_json`, '$.content') WHEN 'array' THEN (SELECT group_concat(json_extract(`part`.`value`, '$.content'), ' ') FROM json_each(`message_json`, '$.content') AS `part` WHERE json_extract(`part`.`value`, '$.type') = 'text') END, ' ' || char(9, 10, 13)), 1, 120), '') FROM `chat_messages` WHERE `chat_messages`.`thread_id` = `sessions`.`id` AND `chat_messages`.`role` = 'user' ORDER BY `chat_messages`.`position` LIMIT 1) WHERE `title` IS NULL AND `harness_session_id` IS NULL;
